        /// <summary>
        /// Report warnings for custom members declared on an inline array struct that will be bypassed
        /// in favor of the built-in element access mechanisms: indexers, 'Slice' methods, and conversion
        /// operators to <see cref="System.Span{T}"/>/<see cref="System.ReadOnlySpan{T}"/>.
        /// </summary>
        private void CheckInlineArrayCustomMembers(BindingDiagnosticBag diagnostics)
        {
            CSharpCompilation compilation = DeclaringCompilation;
            TypeSymbol? elementType = TryGetInlineArrayElementField()?.Type;

            foreach (Symbol member in GetMembers())
            {
                switch (member)
                {
                    case PropertySymbol { IsIndexer: true } indexer:
                        // The built-in element access is always preferred over a user-defined indexer, so warn that
                        // the indexer will not be used. Ref structs cannot be used with the built-in mechanism, so the
                        // indexer is still meaningful there.
                        if (!IsRefLikeType &&
                            !indexer.IsExplicitInterfaceImplementation &&
                            indexer.ParameterCount == 1 &&
                            IsInlineArrayIndexerParameterType(indexer.Parameters[0].Type, compilation))
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArrayIndexerNotUsed, indexer.GetFirstLocation());
                        }
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Ordinary, Name: "Slice" } sliceMethod:
                        if (!sliceMethod.IsExplicitInterfaceImplementation &&
                            !sliceMethod.ReturnsVoid &&
                            sliceMethod.ParameterCount == 2 &&
                            sliceMethod.Parameters[0].Type.SpecialType == SpecialType.System_Int32 &&
                            sliceMethod.Parameters[1].Type.SpecialType == SpecialType.System_Int32)
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArraySliceNotUsed, sliceMethod.GetFirstLocation());
                        }
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Conversion } conversion:
                        if (elementType is not null &&
                            conversion.ParameterCount == 1 &&
                            conversion.Parameters[0].Type.Equals(this, TypeCompareKind.AllIgnoreOptions) &&
                            conversion.ReturnType is NamedTypeSymbol { IsGenericType: true } returnType &&
                            (returnType.OriginalDefinition.Equals(compilation.GetWellKnownType(WellKnownType.System_Span_T), TypeCompareKind.AllIgnoreOptions) ||
                             returnType.OriginalDefinition.Equals(compilation.GetWellKnownType(WellKnownType.System_ReadOnlySpan_T), TypeCompareKind.AllIgnoreOptions)) &&
                            returnType.TypeArgumentsWithAnnotationsNoUseSiteDiagnostics[0].Type.Equals(elementType, TypeCompareKind.AllIgnoreOptions))
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArrayConversionOperatorNotUsed, conversion.GetFirstLocation());
                        }
                        break;
                }
            }
        }

        private static bool IsInlineArrayIndexerParameterType(TypeSymbol type, CSharpCompilation compilation)
        {
            return type.SpecialType == SpecialType.System_Int32 ||
                   type.Equals(compilation.GetWellKnownType(WellKnownType.System_Index), TypeCompareKind.AllIgnoreOptions) ||
                   type.Equals(compilation.GetWellKnownType(WellKnownType.System_Range), TypeCompareKind.AllIgnoreOptions);
        }
    }
